CREATE TABLE IF NOT EXISTS "#__pungacontactform_limits" (
    "ip_hash" CHAR(64) NOT NULL,
    "hour_bucket" BIGINT NOT NULL,
    "attempts" INTEGER NOT NULL DEFAULT 0,
    PRIMARY KEY ("ip_hash", "hour_bucket")
);
CREATE INDEX IF NOT EXISTS "idx_pungacontactform_bucket" ON "#__pungacontactform_limits" ("hour_bucket");

CREATE TABLE IF NOT EXISTS "#__pungacontactform_messages" (
 "id" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
 "created_at" TIMESTAMP NOT NULL,
 "status" VARCHAR(16) NOT NULL,
 "reason" VARCHAR(32) NOT NULL DEFAULT '',
 "source_kind" VARCHAR(16) NOT NULL,
 "source_id" INTEGER NOT NULL DEFAULT 0,
 "is_guest" SMALLINT NOT NULL DEFAULT 1,
 "sender_name" VARCHAR(120) NOT NULL DEFAULT '',
 "sender_email" VARCHAR(254) NOT NULL DEFAULT '',
 "subject" VARCHAR(200) NOT NULL DEFAULT '',
 "body" TEXT NOT NULL,
 "spam_score" INTEGER NOT NULL DEFAULT 0,
 "spam_threshold" INTEGER NOT NULL DEFAULT 0,
 "spam_details" TEXT NOT NULL,
 "archived" SMALLINT NOT NULL DEFAULT 0
);
CREATE INDEX IF NOT EXISTS "idx_pcf_created" ON "#__pungacontactform_messages" ("created_at");
CREATE INDEX IF NOT EXISTS "idx_pcf_status" ON "#__pungacontactform_messages" ("status","archived");
CREATE TABLE IF NOT EXISTS "#__pungacontactform_counts" (
 "day" DATE NOT NULL,
 "status" VARCHAR(16) NOT NULL,
 "total" BIGINT NOT NULL DEFAULT 0,
 PRIMARY KEY ("day", "status")
);
